insert into public.dish (slug,name,protein,category,cuisine,difficulty,tags,occasion,status,source,governance_version,summary,method_md,servings,equipment,designed_unvalidated,nutrition_estimate,legacy_notion_id)
values ($m$coq-au-vin-pommes-puree$m$,$m$Pommes Purée$m$,$m$Veg$m$,array[$m$Side$m$]::text[],array[$m$French$m$]::text[],null,'{}'::text[],array[$m$Family$m$]::text[],$m$designed$m$::dish_status,$m$Adapted from Melissa Clark, NYT Cooking ([cooking.nytimes.com/recipes/1018529-coq-au-vin](http://cooking.nytimes.com/recipes/1018529-coq-au-vin)). Rebuilt under governance v3.5 (2026-07-20); Claude build, GPT cross-checked and reconciled 29 Sep 2026.$m$,$m$v3.5$m$,$m$Smooth, loose, neutral riced-potato purée with butter and warm milk — the carrier for the coq au vin sauce.$m$,$m$# 2. Pommes Purée
*Serves 3 (Lukas full, adults small) · \~45 min · Active \~15 min*
- Overview: smooth, loose, neutral carrier for the sauce. Meal-level texture exemption — purée inherently single-texture; contrast from croutons, lardons, beans.
- Ingredients: 1 lb 2 oz / 500 g Yukon Gold or russet potatoes, peeled, 1¼ in / 3 cm chunks; 50 g / 3½ tbsp unsalted butter, cubed; 120 ml / ½ cup whole milk, warm, + 60 ml / ¼ cup for loosening; 1% salted water (\~15 g Diamond Crystal per 1.5 L).
- Flavor architecture: base butter + milk; primary potato; acid none; finish none.
- Method: cold-water start. Simmer 18–22 min — knife meets no resistance at centre → drain; grips → 3 more min. Steam-dry 1 min. Rice hot; fold in butter, then milk. No blender or processor.
- Holding: Tiger keep-warm (planned max 60 min); loosen at T-4 with warm milk.
- CCP: Major (b) — gluey, stretchy from overworking. Unrecoverable for texture; dish serviceable.
- Adjustment: salt at table. Scaling: N/A.$m$,3,'{}'::text[],$m$[{"param": "Purée keep-warm hold", "designed_value": "Tiger keep-warm 60-min ceiling for purée", "note": "Confirm on first cook: purée keep-warm hold duration and texture."}]$m$::jsonb,null,$m$3e9e0391ce6381078935e7e079fa18ac$m$);
insert into public.dish_ingredient (dish_id,ingredient_id,qty,unit,qty_alt,prep_note,pantry_check,optional,sort_order)
